const raw = $input.first().json;
const src = (raw.body && raw.body.nombre) ? raw.body : raw;
const bin = $input.first().binary;

const uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0;
  return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});

return [{
  json: {
    nombre:             (src.nombre             ?? '').trim(),
    id_estudiante:      (src.id_estudiante      ?? '').trim(),
    correo:             (src.correo             ?? '').trim(),
    motivo:             (src.motivo             ?? '').trim(),
    descripcion:        (src.descripcion        ?? '').trim(),
    fecha_inasistencia: src.fecha_inasistencia ?? '',
    chat_id_telegram:   '',
    fecha_solicitud:    $now.toISO(),
    id_solicitud:       uuid,
    archivo_nombre:     bin?.archivo_soporte?.fileName ?? 'sin_archivo'
  },
  binary: bin
}];

// MEJORA 1: Validacion de formato y tamano de archivo
const datos = $input.first().json;
const bin   = $input.first().binary;

const FORMATOS_PERMITIDOS    = ['image/jpeg','image/jpg','image/png','image/webp','application/pdf'];
const EXTENSIONES_PERMITIDAS = ['jpg','jpeg','png','webp','pdf'];
const TAMANO_MAX_BYTES       = 5 * 1024 * 1024;

let formatoValido = true;
let errorFormato  = '';

if (bin?.archivo_soporte) {
  const mime   = bin.archivo_soporte.mimeType ?? '';
  const tamano = bin.archivo_soporte.fileSize ?? 0;
  const nombre = bin.archivo_soporte.fileName ?? '';
  const ext    = nombre.split('.').pop()?.toLowerCase() ?? '';

  if (!FORMATOS_PERMITIDOS.includes(mime)) {
    formatoValido = false;
    errorFormato  = 'Formato no permitido: ' + mime + '. Solo se aceptan JPG, PNG, WEBP y PDF.';
  } else if (!EXTENSIONES_PERMITIDAS.includes(ext)) {
    formatoValido = false;
    errorFormato  = 'Extension no permitida: .' + ext + '. Extensiones validas: jpg, png, webp, pdf.';
  } else if (tamano > TAMANO_MAX_BYTES) {
    formatoValido = false;
    errorFormato  = 'Archivo demasiado grande (' + Math.round(tamano/1024/1024*10)/10 + ' MB). Maximo permitido: 5 MB.';
  }
}

return [{
  json: { ...datos, formato_valido: formatoValido, error_formato: errorFormato },
  binary: bin
}];

const sheetsItems = $input.all();
const datosOriginales = $('Validar formato de archivo').first().json;
const binaryOriginal  = $('Validar formato de archivo').first().binary;

const esDuplicado = sheetsItems.some(item =>
  item.json.id_estudiante === datosOriginales.id_estudiante &&
  item.json.fecha_inasistencia === datosOriginales.fecha_inasistencia
);

return [{
  json: { ...datosOriginales, es_duplicado: esDuplicado },
  binary: binaryOriginal
}];

const datosBase   = $('Verificar si es duplicado').first().json;
const driveResult = $input.first().json;
const binOrig     = $('Preparar datos solicitud').first().binary;

return [{
  json: {
    ...datosBase,
    tiene_archivo:  true,
    enlace_archivo: driveResult.webViewLink ?? 'Sin archivo',
    drive_file_id:  driveResult.id ?? '',
    mime_archivo:   binOrig?.archivo_soporte?.mimeType ?? ''
  },
  binary: binOrig
}];

const datos = $input.first().json;
const bin   = $input.first().binary;
return [{
  json: {
    ...datos,
    tiene_archivo:  false,
    enlace_archivo: 'Sin archivo',
    drive_file_id:  '',
    mime_archivo:   ''
  },
  binary: bin
}];

// MEJORA 2: Preparar contexto para IA con OCR explicito para imagenes y PDFs
const d   = $input.first().json;
const bin = $('Preparar datos solicitud').first().binary;

let textoArchivo = 'No se adjunto archivo de soporte.';
let tieneImagen  = false;
let imagenBase64 = '';
let imagenMime   = '';
let esOCR        = false;

if (d.tiene_archivo && d.enlace_archivo !== 'Sin archivo') {
  const mime = d.mime_archivo ?? '';

  if (mime.startsWith('image/')) {
    const b64 = bin?.archivo_soporte?.data ?? '';
    if (b64) {
      tieneImagen  = true;
      imagenBase64 = b64;
      imagenMime   = mime;
      esOCR        = true;
      textoArchivo = 'Se adjunto una imagen (' + mime + '). Realiza OCR visual: extrae TODO el texto visible, identifica el tipo de documento (certificado medico, constancia, etc.), fecha del documento, entidad emisora, nombre del paciente/estudiante y cualquier dato relevante. Basa tu clasificacion en este analisis.';
    } else {
      textoArchivo = 'Imagen en Drive (sin base64 disponible): ' + d.enlace_archivo;
    }
  } else if (mime === 'application/pdf') {
    const b64pdf = bin?.archivo_soporte?.data ?? '';
    esOCR = true;
    if (b64pdf) {
      tieneImagen  = true;
      imagenBase64 = b64pdf;
      imagenMime   = mime;
      textoArchivo = 'Se adjunto un PDF. Realiza OCR: extrae el texto completo, identifica tipo de documento, fecha de emision, entidad emisora y nombre del titular. Verifica coherencia con el motivo declarado.';
    } else {
      textoArchivo = 'PDF adjunto en Drive: ' + d.enlace_archivo + '. Toma como evidencia positiva pero no puedes leer su contenido directamente.';
    }
  } else {
    textoArchivo = 'Archivo adjunto: ' + d.archivo_nombre + '. Enlace: ' + d.enlace_archivo;
  }
}

return [{ json: {
  ...d,
  texto_archivo_para_ia: textoArchivo,
  tiene_imagen_agente:   tieneImagen,
  imagen_base64:         imagenBase64,
  imagen_mime:           imagenMime,
  es_ocr:                esOCR
} }];

