  lineasPreguntas + '\n\n' +
  '<i>Por favor envia tus respuestas al correo o contacta al administrador indicando tu ID de solicitud.</i>';

return [{ json: { ...d, mensaje_info_adicional: mensaje } }];

const items = $input.all();
const resultado = [];
for (const item of items) {
  const d = item.json;
  const dest   = String(d.destinatario  ?? '').trim();
  const estado = String(d.estado_envio  ?? '').trim();
  if (estado !== 'PENDIENTE') continue;
  const destValido = dest !== '' && dest !== 'undefined' && dest !== 'null';
  if (!destValido) continue;
  resultado.push({ json: { id_notificacion: d.id_notificacion ?? '', id_solicitud: d.id_solicitud ?? '', canal: d.canal ?? 'TELEGRAM_ESTUDIANTE', destinatario: dest, tipo_mensaje: d.tipo_mensaje ?? '', contenido_mensaje: d.contenido_mensaje ?? '', mensaje_telegram: d.contenido_mensaje ?? '' }, pairedItem: { item: 0 } });
}
return resultado;

const msg  = $input.first().json.message;
const texto = msg?.text?.trim() ?? '';
const chatId = String(msg?.chat?.id ?? '');
const nombreUsuario = msg?.from?.first_name ?? 'Estudiante';
let comando = ''; let parametro = '';
if (texto.startsWith('/start ')) { comando='registrar_chat'; parametro=texto.replace('/start ','').trim(); }
else if (texto === '/start') { comando='bienvenida'; }
else if (texto.startsWith('/consultar ')) { comando='consultar'; parametro=texto.replace('/consultar ','').trim(); }
else if (texto === '/consultar') { comando='consultar_sin_id'; }
else if (texto.startsWith('/historial')) { comando='historial'; }
else if (texto === '/ayuda' || texto === '/help') { comando='ayuda'; }
else { comando='desconocido'; }
return [{ json: { comando, parametro, chat_id: chatId, nombre_usuario: nombreUsuario } }];

const resultado    = $input.all();
const datosComando = $('Parsear comando Telegram').first().json;
const solicitud    = resultado.find(item => item.json.id_solicitud && item.json.id_solicitud !== '');
if (!solicitud) { return [{ json: { encontrado: false, chat_id: datosComando.chat_id, parametro: datosComando.parametro } }]; }
const s = solicitud.json;
const estadoEmoji = s.estado === 'APROBADA' ? '✅' : s.estado === 'RECHAZADA' ? '❌' : '⏳';
return [{ json: { encontrado: true, chat_id: datosComando.chat_id, id_solicitud: s.id_solicitud ?? 'N/A', nombre: s.nombre ?? 'N/A', motivo: s.motivo ?? 'N/A', fecha_inasistencia: s.fecha_inasistencia ?? 'N/A', estado: s.estado ?? 'DESCONOCIDO', estado_emoji: estadoEmoji, razon_ia: s.razon_ia ?? 'N/A', nivel_confianza: s.nivel_confianza ?? 'N/A', hallazgos_doc: s.hallazgos_doc ?? 'Sin analisis', fecha_solicitud: s.fecha_solicitud ?? 'N/A', enlace_archivo: s.enlace_archivo ?? 'Sin archivo', palabras_clave: s.palabras_clave ?? '' } }];

const d = $input.first().json;
const lineas = [];
lineas.push(d.estado_emoji + ' <b>Solicitud ' + d.id_solicitud + '</b>');
lineas.push('');
lineas.push('👤 Estudiante: ' + d.nombre);
