lineas.push('📁 Archivo: ' + d.enlace_archivo);
return [{ json: { ...d, mensaje_consulta: lineas.join('\n') } }];

const resultados   = $input.all();
const datosComando = $('Parsear comando Telegram').first().json;
const solicitudes = resultados.filter(item => item.json.id_solicitud && item.json.id_solicitud !== '').slice(-5).reverse();
if (solicitudes.length === 0) { return [{ json: { chat_id: datosComando.chat_id, mensaje: '📭 No tienes solicitudes registradas.

Accede al formulario web para enviar tu primera justificacion.' } }]; }
const lineas = solicitudes.map(item => { const s = item.json; const emoji = s.estado === 'APROBADA' ? '✅' : s.estado === 'RECHAZADA' ? '❌' : '⏳'; return emoji + ' <code>' + (s.id_solicitud ?? 'N/A') + '</code>
