<i>Usa /consultar ID para ver detalles.</i>';
return [{ json: { chat_id: datosComando.chat_id, mensaje } }];

const fila = $input.first().json;

// Aceptar tanto body anidado como plano
const d = (fila.body && fila.body.id_solicitud) ? fila.body : fila;

const estadosFinales = ['APROBADA', 'RECHAZADA'];
const esManual =
  estadosFinales.includes((d.estado ?? '').trim().toUpperCase()) &&
